<?php
require_once __DIR__.'/../includes/user-check.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT d.*,m.kode motor_kode,m.nama motor_nama,m.merek,m.tahun,k.kode kerusakan_kode,k.nama kerusakan_nama,k.deskripsi kerusakan_deskripsi FROM diagnosis d JOIN motor m ON m.id=d.motor_id LEFT JOIN kerusakan k ON k.id=d.kerusakan_id WHERE d.id=? AND d.user_id=?');$q->execute([$id,(int)$_SESSION['user']['id']]);$d=$q->fetch();if(!$d){http_response_code(404);exit('Hasil diagnosis tidak ditemukan.');}$q=$pdo->prepare('SELECT g.kode,g.nama,dg.jawaban FROM diagnosis_gejala dg JOIN gejala g ON g.id=dg.gejala_id WHERE dg.diagnosis_id=? ORDER BY g.kode');$q->execute([$id]);$answers=$q->fetchAll();$yes=array_values(array_filter($answers,static fn($r)=>$r['jawaban']==='YA'));$no=array_values(array_filter($answers,static fn($r)=>$r['jawaban']==='TIDAK'));$solutions=[];if($d['kerusakan_id']){$q=$pdo->prepare('SELECT deskripsi FROM solusi WHERE kerusakan_id=? ORDER BY id');$q->execute([(int)$d['kerusakan_id']]);$solutions=$q->fetchAll();}$found=$d['kerusakan_id']!==null;$page_title='Hasil Diagnosis';require __DIR__.'/../includes/header.php';
?><section class="app-content-header"><div class="container-fluid"><h3>Hasil Diagnosis</h3></div></section><section class="content"><div class="container-fluid"><div class="card border-<?= $found?'success':'warning' ?>"><div class="card-header"><h3 class="card-title"><?= $found?'Kerusakan Terdeteksi':'Belum Ditemukan Aturan yang Cocok' ?></h3></div><div class="card-body"><p><strong>Motor:</strong> <?= e($d['motor_kode'].' - '.$d['merek'].' '.$d['motor_nama'].($d['tahun']?' '.$d['tahun']:'')) ?></p><?php if($found): ?><div class="callout callout-success"><h4><?= e($d['kerusakan_kode'].' - '.$d['kerusakan_nama']) ?></h4><?php if($d['kerusakan_deskripsi']): ?><p><?= e($d['kerusakan_deskripsi']) ?></p><?php endif ?></div><?php else: ?><div class="alert alert-warning">Jawaban Anda belum memenuhi semua gejala pada aturan aktif mana pun. Sistem tidak memaksakan hasil kerusakan.</div><?php endif ?><p class="small text-body-secondary">Metode Forward Chaining memeriksa terpenuhi atau tidaknya seluruh kondisi aturan; tidak ada persentase kecocokan yang ditambahkan.</p><p><strong>Waktu diagnosis:</strong> <?= e(date('d-m-Y H:i',strtotime($d['created_at']))) ?></p></div></div><div class="row"><div class="col-lg-6"><div class="card"><div class="card-header">Gejala dijawab YA (<?= count($yes) ?>)</div><div class="card-body"><?php if($yes): ?><ul class="mb-0"><?php foreach($yes as $g): ?><li><strong><?= e($g['kode']) ?></strong> - <?= e($g['nama']) ?></li><?php endforeach ?></ul><?php else: ?><p class="mb-0">Tidak ada.</p><?php endif ?></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header">Gejala dijawab TIDAK (<?= count($no) ?>)</div><div class="card-body"><?php if($no): ?><ul class="mb-0"><?php foreach($no as $g): ?><li><strong><?= e($g['kode']) ?></strong> - <?= e($g['nama']) ?></li><?php endforeach ?></ul><?php else: ?><p class="mb-0">Tidak ada.</p><?php endif ?></div></div></div></div><?php if($found): ?><div class="card"><div class="card-header">Solusi</div><div class="card-body"><?php if($solutions): ?><ol><?php foreach($solutions as $s): ?><li><?= nl2br(e($s['deskripsi'])) ?></li><?php endforeach ?></ol><?php else: ?><p class="mb-0">Belum ada solusi tercatat untuk kerusakan ini. Hubungi administrator.</p><?php endif ?></div></div><?php endif ?><div class="d-flex gap-2 mb-4"><a class="btn btn-primary" href="diagnosis.php">Diagnosis Lagi</a><a class="btn btn-outline-secondary" href="riwayat.php">Lihat Riwayat</a></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
